using UnityEngine;using UnityEngine.UI;
namespace BackendPRO {public class LoginPanel:MonoBehaviour {public GameAuth auth;public InputField email,password,securityKey;public Text status;void OnEnable(){auth.Status+=Show;}void OnDisable(){auth.Status-=Show;}void Show(string s){status.text=s;if(securityKey!=null&&!string.IsNullOrEmpty(auth.IssuedSecurityKey)){securityKey.text=auth.IssuedSecurityKey;status.text+=" - Copy and save your new key";}}public void Login()=>auth.Login(email.text,password.text,securityKey!=null?securityKey.text:"");public void Register()=>auth.Register(email.text,password.text);public void Load()=>auth.LoadPlayer();public void Logout(){if(securityKey!=null)securityKey.text="";auth.Logout();}public void CopyKey(){if(securityKey!=null)GUIUtility.systemCopyBuffer=securityKey.text;}}}
